Use a character-list CRDT (RGA-style): each insert gets a unique `CharId`, deletes are tombstones, and merge is the union of ops. Concurrent inserts after the same parent sort by `CharId`. That is strong eventual consistency — same op set ⇒ same text — without a central lock. OT can also converge but needs a transform function (usually server-mediated). Full-string LWW picks `cut` or `cats` and silently drops the other edit, so it never yields `cuts`.

```python
# ch6_text_crdt.py
# Lab: character-list CRDT merge for collaborative text (DDIA ch6)
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Optional


@dataclass(frozen=True, order=True)
class CharId:
    replica: str
    counter: int


@dataclass
class Char:
    id: CharId
    value: str
    after: Optional[CharId]
    deleted: bool = False


@dataclass
class Replica:
    name: str
    counter: int = 0
    chars: dict[CharId, Char] = field(default_factory=dict)
    seen: set[tuple[str, CharId]] = field(default_factory=set)
    tombstones: set[CharId] = field(default_factory=set)

    def _next_id(self) -> CharId:
        self.counter += 1
        return CharId(self.name, self.counter)

    def seed(self, text: str) -> None:
        """Identical origin ids on every replica so concurrent edits share anchors."""
        prev: Optional[CharId] = None
        for i, ch in enumerate(text, start=1):
            cid = CharId("origin", i)
            self.chars[cid] = Char(cid, ch, prev, False)
            self.seen.add(("insert", cid))
            prev = cid

    def text(self) -> str:
        children: dict[Optional[CharId], list[CharId]] = {}
        for cid, c in self.chars.items():
            children.setdefault(c.after, []).append(cid)
        for kids in children.values():
            kids.sort()  # deterministic tie-break for concurrent inserts after same anchor
        out: list[str] = []

        def walk(after: Optional[CharId]) -> None:
            for cid in children.get(after, []):
                c = self.chars[cid]
                if not c.deleted:
                    out.append(c.value)
                walk(cid)

        walk(None)
        return "".join(out)

    def apply(self, op: dict[str, Any]) -> None:
        key = (op["type"], op["id"])
        if key in self.seen:
            return
        self.seen.add(key)
        if op["type"] == "insert":
            cid = op["id"]
            self.chars[cid] = Char(
                cid, op["value"], op["after"], cid in self.tombstones
            )
        elif op["type"] == "delete":
            target = op["target"]
            self.tombstones.add(target)
            if target in self.chars:
                self.chars[target].deleted = True

    def insert_after(self, after: Optional[CharId], value: str) -> dict[str, Any]:
        cid = self._next_id()
        op: dict[str, Any] = {
            "type": "insert",
            "id": cid,
            "after": after,
            "value": value,
        }
        self.apply(op)
        return op

    def delete(self, target: CharId) -> dict[str, Any]:
        oid = self._next_id()
        op: dict[str, Any] = {"type": "delete", "id": oid, "target": target}
        self.apply(op)
        return op

    def merge(self, remote_ops: list[dict[str, Any]]) -> None:
        for op in remote_ops:
            self.apply(op)


def demo_crdt() -> tuple[str, str]:
    a, b = Replica("A"), Replica("B")
    a.seed("cat")
    b.seed("cat")
    c_id, a_id, t_id = CharId("origin", 1), CharId("origin", 2), CharId("origin", 3)

    # A: replace 'a' with 'u' → cut
    ops_a = [a.delete(a_id), a.insert_after(c_id, "u")]
    # B: append 's' → cats
    ops_b = [b.insert_after(t_id, "s")]

    a.merge(ops_b)
    b.merge(ops_a)
    return a.text(), b.text()


def demo_lww() -> str:
    # wall-clock / version LWW on the whole document string
    versions = [("A", "cut", 1), ("B", "cats", 2)]
    winner = max(versions, key=lambda row: row[2])
    return winner[1]


def assert_delete_insert_commute() -> None:
    # delete-before-insert and insert-before-delete must both leave the char gone
    x = CharId("X", 1)
    ins = {"type": "insert", "id": x, "after": None, "value": "z"}
    dele = {"type": "delete", "id": CharId("X", 2), "target": x}
    r1, r2 = Replica("T1"), Replica("T2")
    for op in (dele, ins):
        r1.apply(op)
    for op in (ins, dele):
        r2.apply(op)
    assert r1.text() == r2.text() == ""


if __name__ == "__main__":
    left, right = demo_crdt()
    print("CRDT sync:", left, right)
    print("LWW full-string:", demo_lww())
    assert left == right == "cuts"
    assert demo_lww() in ("cut", "cats") and demo_lww() != "cuts"
    assert_delete_insert_commute()
```

Comment: Google Docs historically used OT; many local-first editors (Yjs, Automerge) use list CRDTs with the same tombstone + unique-id pattern.

Use an RGA-style list CRDT: each playlist slot gets a unique `ElementId`, deletes are durable tombstones, and merge is the union of ops. Concurrent inserts after the same parent sort by `ElementId`. Phone's delete of `t2` and insert of `t4` (offline `['t1', 't3', 't4']`), plus tablet's delete+re-insert of `t3` at head (offline stays `['t1', 't2', 't3']` under ascending tie-break), all survive sync and converge to `['t1', 't4', 't3']`. Naive set-union of track IDs resurrects deleted `t2`. Full-list LWW keeps one device's offline order and silently drops the other's edits.

```python
# ch6_playlist_crdt.py
# Lab: RGA-style ordered-list CRDT for multi-leader playlists (DDIA ch6)
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Optional


@dataclass(frozen=True, order=True)
class ElementId:
    replica: str
    counter: int


@dataclass
class Element:
    id: ElementId
    track: str
    after: Optional[ElementId]
    deleted: bool = False


@dataclass
class Replica:
    name: str
    counter: int = 0
    elems: dict[ElementId, Element] = field(default_factory=dict)
    seen: set[tuple[str, ElementId]] = field(default_factory=set)
    tombstones: set[ElementId] = field(default_factory=set)

    def _next_id(self) -> ElementId:
        self.counter += 1
        return ElementId(self.name, self.counter)

    def seed(self, tracks: list[str]) -> None:
        """Identical origin ids on every replica so concurrent edits share anchors."""
        prev: Optional[ElementId] = None
        for i, track in enumerate(tracks, start=1):
            eid = ElementId("origin", i)
            self.elems[eid] = Element(eid, track, prev, False)
            self.seen.add(("insert", eid))
            prev = eid

    def tracks(self) -> list[str]:
        children: dict[Optional[ElementId], list[ElementId]] = {}
        for eid, el in self.elems.items():
            children.setdefault(el.after, []).append(eid)
        for kids in children.values():
            kids.sort()  # deterministic tie-break for concurrent inserts after same anchor
        out: list[str] = []

        def walk(after: Optional[ElementId]) -> None:
            for eid in children.get(after, []):
                el = self.elems[eid]
                if not el.deleted:
                    out.append(el.track)
                walk(eid)

        walk(None)
        return out

    def apply(self, op: dict[str, Any]) -> None:
        key = (op["type"], op["id"])
        if key in self.seen:
            return
        self.seen.add(key)
        if op["type"] == "insert":
            eid = op["id"]
            self.elems[eid] = Element(
                eid, op["track"], op["after"], eid in self.tombstones
            )
        elif op["type"] == "delete":
            target = op["target"]
            self.tombstones.add(target)
            if target in self.elems:
                self.elems[target].deleted = True

    def insert_after(self, after: Optional[ElementId], track: str) -> dict[str, Any]:
        eid = self._next_id()
        op: dict[str, Any] = {
            "type": "insert",
            "id": eid,
            "after": after,
            "track": track,
        }
        self.apply(op)
        return op

    def delete(self, target: ElementId) -> dict[str, Any]:
        oid = self._next_id()
        op: dict[str, Any] = {"type": "delete", "id": oid, "target": target}
        self.apply(op)
        return op

    def merge(self, remote_ops: list[dict[str, Any]]) -> None:
        for op in remote_ops:
            self.apply(op)


def demo_crdt() -> tuple[list[str], list[str]]:
    phone, tablet = Replica("phone"), Replica("tablet")
    phone.seed(["t1", "t2", "t3"])
    tablet.seed(["t1", "t2", "t3"])
    e1, e2, e3 = ElementId("origin", 1), ElementId("origin", 2), ElementId("origin", 3)

    # Phone: remove t2, add t4 after t1 → local tracks() [t1, t3, t4]
    ops_phone = [phone.delete(e2), phone.insert_after(e1, "t4")]
    # Tablet: delete origin t3, re-insert t3 at head → local tracks() [t1, t2, t3]
    ops_tablet = [tablet.delete(e3), tablet.insert_after(None, "t3")]

    phone.merge(ops_tablet)
    tablet.merge(ops_phone)
    return phone.tracks(), tablet.tracks()


def demo_set_union() -> set[str]:
    phone_offline = {"t1", "t3", "t4"}
    tablet_offline = {"t1", "t2", "t3"}
    return phone_offline | tablet_offline


def demo_lww() -> list[str]:
    # wall-clock / version LWW on the whole ordered list (real offline tracks())
    versions = [
        ("phone", ["t1", "t3", "t4"], 1),
        ("tablet", ["t1", "t2", "t3"], 2),
    ]
    winner = max(versions, key=lambda row: row[2])
    return winner[1]


def assert_delete_insert_commute() -> None:
    # delete-before-insert and insert-before-delete must both leave the slot gone
    x = ElementId("X", 1)
    ins = {"type": "insert", "id": x, "after": None, "track": "z"}
    dele = {"type": "delete", "id": ElementId("X", 2), "target": x}
    r1, r2 = Replica("T1"), Replica("T2")
    for op in (dele, ins):
        r1.apply(op)
    for op in (ins, dele):
        r2.apply(op)
    assert r1.tracks() == r2.tracks() == []


if __name__ == "__main__":
    left, right = demo_crdt()
    print("CRDT sync:", left, right)
    print("Set-union tracks:", sorted(demo_set_union()))
    print("LWW full-list:", demo_lww())
    assert left == right == ["t1", "t4", "t3"]
    assert "t2" in demo_set_union()
    assert demo_lww() in (["t1", "t3", "t4"], ["t1", "t2", "t3"])
    assert_delete_insert_commute()
```

Comment: Automerge `List` CRDT and Yjs `Y.Array` implement this tombstone + unique-id pattern for local-first apps; Spotify-style server-authoritative playlists avoid the problem by using single-leader writes.

Version-number sibling detection: each write carries the `base_version` from the client's last read. The server deletes siblings with `version <= base_version` (those the client already merged) and keeps strictly higher versions as concurrent siblings. After the five writes, cart-42 still has two siblings — v4 and v5 — because neither write's base covered the other.

```sql
-- ch6_cart_siblings.sql
-- Lab: version-number sibling detection for concurrent shopping-cart writes (DDIA ch6)
DROP TABLE IF EXISTS ch6_cart_siblings CASCADE;
DROP TABLE IF EXISTS ch6_cart_ops CASCADE;

CREATE TABLE ch6_cart_siblings (
  cart_id    TEXT NOT NULL,
  version    INT  NOT NULL,
  items      JSONB NOT NULL,
  PRIMARY KEY (cart_id, version)
);

CREATE TABLE ch6_cart_ops (
  op_id        SERIAL PRIMARY KEY,
  cart_id      TEXT NOT NULL,
  client_id    TEXT NOT NULL,
  base_version INT,
  items        JSONB NOT NULL,
  created_at   TIMESTAMPTZ DEFAULT now()
);

INSERT INTO ch6_cart_siblings (cart_id, version, items) VALUES
  ('cart-42', 0, '[]'::jsonb);

CREATE OR REPLACE FUNCTION ch6_apply_cart_write(
  p_cart_id TEXT,
  p_client_id TEXT,
  p_base_version INT,
  p_new_items JSONB
) RETURNS INT
LANGUAGE plpgsql AS $$
DECLARE
  v_new INT;
BEGIN
  INSERT INTO ch6_cart_ops (cart_id, client_id, base_version, items)
  VALUES (p_cart_id, p_client_id, p_base_version, p_new_items);

  SELECT COALESCE(MAX(version), 0) + 1 INTO v_new
  FROM ch6_cart_siblings
  WHERE cart_id = p_cart_id;

  IF p_base_version IS NOT NULL THEN
    DELETE FROM ch6_cart_siblings
    WHERE cart_id = p_cart_id
      AND version <= p_base_version;
  END IF;

  INSERT INTO ch6_cart_siblings (cart_id, version, items)
  VALUES (p_cart_id, v_new, p_new_items);

  RETURN v_new;
END;
$$;

-- Five writes (chapter shopping-cart sequence)
SELECT ch6_apply_cart_write('cart-42', 'client-1', 0, '["milk"]'::jsonb);
SELECT ch6_apply_cart_write('cart-42', 'client-2', 0, '["eggs"]'::jsonb);
SELECT ch6_apply_cart_write('cart-42', 'client-1', 1, '["milk","flour"]'::jsonb);
SELECT ch6_apply_cart_write('cart-42', 'client-2', 2, '["eggs","milk","ham"]'::jsonb);
SELECT ch6_apply_cart_write('cart-42', 'client-1', 3, '["milk","flour","eggs"]'::jsonb);

SELECT version, items
FROM ch6_cart_siblings
WHERE cart_id = 'cart-42'
ORDER BY version;
--  4 | ["eggs", "milk", "ham"]
--  5 | ["milk", "flour", "eggs"]
```

Happens-before vs concurrent for this run (rule: A → B when B.base_version >= A.version; otherwise concurrent if neither covers the other):
- W1 → W3: W3 base 1 covers W1/v1.
- W1 → W4: W4 base 2 covers W1/v1 (2 >= 1), so W4 overwrites W1 even though W4 never based on v1 directly.
- W2 → W4: W4 base 2 covers W2/v2.
- W2 → W5: W5 base 3 covers W2/v2 (3 >= 2), so W5 overwrites W2.
- W3 → W5: W5 base 3 covers W3/v3.
- Concurrent: W1 ∥ W2 (both base 0); W3 ∥ W4 (neither base covers the other: W4 base 2 < v3, W3 base 1 < v4); W4 ∥ W5 (final siblings: W5 base 3 < v4, W4 base 2 < v5). Transitive HB (e.g. W1 → W3 → W5) follows from the same base_version rule.

Production merge of remaining siblings should use a set-union CRDT with tombstones — not a plain `DISTINCT` array union (that resurrects deleted cart lines). For this lab, the hand-built arrays document why sibling detection alone is not enough.

Multi-replica extension: replace the single `INT version` with a `JSONB` version vector such as `{"r1":3,"r2":2}`. Each replica increments its own counter and tracks versions seen from others; two writes are concurrent when neither vector dominates component-wise.

Read path that returns all siblings for client-side merge:

```sql
SELECT jsonb_agg(items)
FROM ch6_cart_siblings
WHERE cart_id = 'cart-42';
```

A write with `base_version` NULL deletes nothing — it is concurrent with every existing sibling and will appear on subsequent reads until a later merge covers it.

Operational note: monitor sibling count per key; sustained growth means unresolved conflicts. Riak exposes siblings in API responses the same way; DynamoDB conditional writes are the managed form of sending the version observed by the prior read.

practice.question:
A profile API writes to the primary and normally reads from a replica. After a user updates their bio, an immediate GET sometimes returns the old bio (replication lag).

This lab uses one lag model only: a stale snapshot table `ch6_profiles_replica` that you refresh manually (no real physical replica required). Redis is optional discussion for production last-write tracking — not required to run the lab.

Prerequisites: PostgreSQL 16+ with `psql` on your PATH.

```bash
# macOS
brew install postgresql@16
brew services start postgresql@16

# Debian/Ubuntu
sudo apt install postgresql

# Confirm install
psql --version
```

Save the file below as `ch6_profile_ryw.sql`, then apply it with `psql -f ch6_profile_ryw.sql`. Complete the stubs at the `-- implement` comments (Task 2) before relying on `ch6_write_profile` / `ch6_read_profile`. `ch6_refresh_replica` already works and copies primary → replica to simulate catch-up.

Expected signals:
- Task 1: after the primary UPDATE, `SELECT bio FROM ch6_profiles_replica WHERE user_id = 101` prints `Engineer`; the matching primary SELECT prints `Staff engineer`.
- Task 2: `SELECT * FROM ch6_write_profile(101, 'Staff engineer')` then `SELECT * FROM ch6_read_profile(101)` prints `src=primary` and bio `Staff engineer`; `SELECT * FROM ch6_read_profile(202)` prints `src=replica`. After `SELECT ch6_refresh_replica()` and aging user 101's last write past 60s, `ch6_read_profile(101)` prints `src=replica`.

```sql
-- ch6_profile_ryw.sql
-- Lab: async replica lag + read-your-writes routing for profiles (DDIA ch6)
DROP TABLE IF EXISTS ch6_last_write CASCADE;
DROP TABLE IF EXISTS ch6_profiles_replica CASCADE;
DROP TABLE IF EXISTS ch6_profiles CASCADE;
DROP FUNCTION IF EXISTS ch6_refresh_replica();
DROP FUNCTION IF EXISTS ch6_write_profile(BIGINT, TEXT);
DROP FUNCTION IF EXISTS ch6_read_profile(BIGINT);
DROP FUNCTION IF EXISTS ch6_wait_replica_lsn(pg_lsn, INTERVAL);

CREATE TABLE ch6_profiles (
  user_id       BIGINT PRIMARY KEY,
  display_name  TEXT NOT NULL,
  bio           TEXT NOT NULL DEFAULT ''
);

-- Stale snapshot standing in for an async physical replica
CREATE TABLE ch6_profiles_replica (LIKE ch6_profiles INCLUDING ALL);

-- Per-user last-write gate for read-your-writes (app metadata; Redis in production)
CREATE TABLE ch6_last_write (
  user_id    BIGINT PRIMARY KEY,
  written_at TIMESTAMPTZ NOT NULL,
  write_lsn  pg_lsn
);

INSERT INTO ch6_profiles (user_id, display_name, bio) VALUES
  (101, 'Alice', 'Engineer'),
  (202, 'Bob',   'Designer');

INSERT INTO ch6_profiles_replica SELECT * FROM ch6_profiles;

-- Already working: simulate replica catch-up
CREATE OR REPLACE FUNCTION ch6_refresh_replica()
RETURNS void
LANGUAGE sql AS $$
  TRUNCATE ch6_profiles_replica;
  INSERT INTO ch6_profiles_replica SELECT * FROM ch6_profiles;
$$;

CREATE OR REPLACE FUNCTION ch6_write_profile(p_user_id BIGINT, p_bio TEXT)
RETURNS TABLE(user_id BIGINT, bio TEXT, written_at TIMESTAMPTZ)
LANGUAGE plpgsql AS $$
BEGIN
  -- implement: UPDATE ch6_profiles bio; upsert ch6_last_write
  --   (written_at = now(), write_lsn = pg_current_wal_lsn()); return the row
  RAISE EXCEPTION 'not implemented';
END;
$$;

CREATE OR REPLACE FUNCTION ch6_read_profile(p_user_id BIGINT)
RETURNS TABLE(src TEXT, user_id BIGINT, bio TEXT)
LANGUAGE plpgsql AS $$
BEGIN
  -- implement read-your-writes routing:
  --   if this user has ch6_last_write.written_at within the last 60 seconds
  --   → SELECT from ch6_profiles (primary), src = 'primary'
  --   else → SELECT from ch6_profiles_replica, src = 'replica'
  -- optional implement: call ch6_wait_replica_lsn(write_lsn) before replica read
  RAISE EXCEPTION 'not implemented';
END;
$$;

-- Optional LSN-wait stub (not required for Tasks 1–2; discuss in Task 3)
CREATE OR REPLACE FUNCTION ch6_wait_replica_lsn(
  p_write_lsn pg_lsn,
  p_timeout INTERVAL DEFAULT interval '2 seconds'
) RETURNS BOOLEAN
LANGUAGE plpgsql AS $$
BEGIN
  -- implement (optional): in a real cluster, poll pg_stat_replication.replay_lsn
  --   until replay_lsn >= p_write_lsn or timeout; return true if caught up
  -- This lab's stale-snapshot model has no WAL receiver — leave as stub or
  --   return false and let ch6_read_profile fall back to primary via the 60s gate
  RAISE EXCEPTION 'not implemented';
END;
$$;
```

Task 1 — reproduce stale bio (raw SQL; functions may still be stubs). Reset seed state if needed, then run:

```sql
