practice.answer:
Async followers can lag, so a read-after-write of your own profile can miss the new bio. Fix read-your-writes at the app layer: after a write, record `written_at` (and optionally `write_lsn`) per user; for ~60s route that user's profile reads to the primary while other users keep reading the replica. Lag model here is a stale snapshot table refreshed only by `ch6_refresh_replica()`.

```sql
-- ch6_profile_ryw.sql
-- Lab: async replica lag + read-your-writes routing for profiles (DDIA ch6)
DROP TABLE IF EXISTS ch6_last_write CASCADE;
DROP TABLE IF EXISTS ch6_profiles_replica CASCADE;
DROP TABLE IF EXISTS ch6_profiles CASCADE;
DROP FUNCTION IF EXISTS ch6_refresh_replica();
DROP FUNCTION IF EXISTS ch6_write_profile(BIGINT, TEXT);
DROP FUNCTION IF EXISTS ch6_read_profile(BIGINT);
DROP FUNCTION IF EXISTS ch6_wait_replica_lsn(pg_lsn, INTERVAL);

CREATE TABLE ch6_profiles (
  user_id       BIGINT PRIMARY KEY,
  display_name  TEXT NOT NULL,
  bio           TEXT NOT NULL DEFAULT ''
);

CREATE TABLE ch6_profiles_replica (LIKE ch6_profiles INCLUDING ALL);

CREATE TABLE ch6_last_write (
  user_id    BIGINT PRIMARY KEY,
  written_at TIMESTAMPTZ NOT NULL,
  write_lsn  pg_lsn
);

INSERT INTO ch6_profiles (user_id, display_name, bio) VALUES
  (101, 'Alice', 'Engineer'),
  (202, 'Bob',   'Designer');

INSERT INTO ch6_profiles_replica SELECT * FROM ch6_profiles;

CREATE OR REPLACE FUNCTION ch6_refresh_replica()
RETURNS void
LANGUAGE sql AS $$
  TRUNCATE ch6_profiles_replica;
  INSERT INTO ch6_profiles_replica SELECT * FROM ch6_profiles;
$$;

CREATE OR REPLACE FUNCTION ch6_write_profile(p_user_id BIGINT, p_bio TEXT)
RETURNS TABLE(user_id BIGINT, bio TEXT, written_at TIMESTAMPTZ)
LANGUAGE plpgsql AS $$
DECLARE
  v_at TIMESTAMPTZ := now();
  v_lsn pg_lsn := pg_current_wal_lsn();
BEGIN
  UPDATE ch6_profiles
  SET bio = p_bio
  WHERE ch6_profiles.user_id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown user_id %', p_user_id;
  END IF;

  INSERT INTO ch6_last_write AS lw (user_id, written_at, write_lsn)
  VALUES (p_user_id, v_at, v_lsn)
  ON CONFLICT (user_id) DO UPDATE
  SET written_at = EXCLUDED.written_at,
      write_lsn  = EXCLUDED.write_lsn;

  RETURN QUERY
  SELECT p_user_id, p_bio, v_at;
END;
$$;

CREATE OR REPLACE FUNCTION ch6_read_profile(p_user_id BIGINT)
RETURNS TABLE(src TEXT, user_id BIGINT, bio TEXT)
LANGUAGE plpgsql AS $$
DECLARE
  v_recent BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM ch6_last_write lw
    WHERE lw.user_id = p_user_id
      AND lw.written_at > now() - interval '60 seconds'
  ) INTO v_recent;

  IF v_recent THEN
    RETURN QUERY
    SELECT 'primary'::TEXT, p.user_id, p.bio
    FROM ch6_profiles p
    WHERE p.user_id = p_user_id;
  ELSE
    RETURN QUERY
    SELECT 'replica'::TEXT, r.user_id, r.bio
    FROM ch6_profiles_replica r
    WHERE r.user_id = p_user_id;
  END IF;
END;
$$;

